  const choiceField = (id,label,items,opts={}) => `<div class="field ${opts.full?'full':''}"><span class="field-label">${label}${opts.hint?`<span class="hint">${opts.hint}</span>`:''}</span><div class="choice-row">${items.map((x,i)=>`<div class="choice"><input type="radio" id="${id}_${i}" name="${id}" value="${x[0]}" ${i===0?'checked':''}><label for="${id}_${i}">${x[1]}</label></div>`).join('')}</div></div>`;
